        method?: unknown;
        params?: {
            name?: unknown;
            arguments?: unknown;
        };
    } | null;
    const id = typeof r?.id === 'string' && /^[a-zA-Z0-9._-]{1,80}$/.test(r.id) || typeof r?.id === 'number' && Number.isSafeInteger(r.id) ? r.id : null;
